INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5722392, 831773, 37444, '<td valign="top">heh heh - I am so glad I did not go to Old Town for this shot :) though I did consider it. 9</td>', 'heh heh - I am so glad I did not go to Old Town for this shot :) though I did consider it. 9', '2009-11-11 00:03:34.000000', NULL, 1),
(5722432, 832848, 110744, '<td valign="top">Interesting lighting. Curious to know how you did this - backlighting?</td>', 'Interesting lighting. Curious to know how you did this - backlighting?', '2009-11-11 00:14:59.000000', NULL, 1),
(5722462, 832856, 110744, '<td valign="top">Lovely! I had a similar idea to this shot but I didn''t end up going with it. And it was nowhere near as good as this!</td>', 'Lovely! I had a similar idea to this shot but I didn''t end up going with it. And it was nowhere near as good as this!', '2009-11-11 00:26:39.000000', NULL, 1),
(5722502, 832913, 56579, '<td valign="top">If the focus was sharper I would give it at least another point or two</td>', 'If the focus was sharper I would give it at least another point or two', '2009-11-11 00:43:18.000000', NULL, 1),
(5722508, 832701, 56579, '<td valign="top">Looks a little unlevel to me...It seems like the left side is too low</td>', 'Looks a little unlevel to me...It seems like the left side is too low', '2009-11-11 00:46:02.000000', NULL, 1),
(5722512, 832681, 56579, '<td valign="top">Photo is too noisy....I think the black and white make a simple subject look even less interesting....Being black and white certainly does not add anything to it in my opinion</td>', 'Photo is too noisy....I think the black and white make a simple subject look even less interesting....Being black and white certainly does not add anything to it in my opinion', '2009-11-11 00:47:16.000000', NULL, 1),
(5722527, 832732, 56579, '<td valign="top">Focus on the background needs to be sharper</td>', 'Focus on the background needs to be sharper', '2009-11-11 00:52:12.000000', NULL, 1),
(5722534, 832150, 56579, '<td valign="top">I don''t see the symmetry, repetition is not the same thing<br/> <br/>I am sure you will get a lower score from others on DPC for the same reason</td>', 'I don''t see the symmetry, repetition is not the same thing I am sure you will get a lower score from others on DPC for the same reason', '2009-11-11 00:56:24.000000', NULL, 1),
(5722548, 832919, 56579, '<td valign="top">The subject looks more like a texture than a symmetry, Yes it has symmetry, but it does not exhibit it in the way most will think of.<br/> <br/>But the biggest reason I lowered my score is because I think the black and white makes this photo less interesting than it would be in colour.  There is no definition of lines or structure, giving it less colour definition only makes it less interesting.</td>', 'The subject looks more like a texture than a symmetry, Yes it has symmetry, but it does not exhibit it in the way most will think of. But the biggest reason I lowered my score is because I think the black and white makes this photo less interesting than it would be in colour.  There is no definition of lines or structure, giving it less colour definition only makes it less interesting.', '2009-11-11 01:10:13.000000', NULL, 1),
(5722550, 832080, 7756, '<td valign="top">nice shot a ribbon im sure</td>', 'nice shot a ribbon im sure', '2009-11-11 01:12:46.000000', NULL, 1),
(5722551, 832587, 56579, '<td valign="top">a smaller aperture would IMO improve this photo....I can''t tell what point you were trying to focus on if you were trying to make it fuzzy in the forground and fuzzy in the background...a smaller aperture might help your lens bring out some sharpness assuming that the above statement was not your goal</td>', 'a smaller aperture would IMO improve this photo....I can''t tell what point you were trying to focus on if you were trying to make it fuzzy in the forground and fuzzy in the background...a smaller aperture might help your lens bring out some sharpness assuming that the above statement was not your goal', '2009-11-11 01:12:47.000000', NULL, 1),
(5722555, 831796, 7756, '<td valign="top">love it! took a few seconds to work out what it was. ribbon!</td>', 'love it! took a few seconds to work out what it was. ribbon!', '2009-11-11 01:14:13.000000', NULL, 1),
(5722558, 832827, 7756, '<td valign="top">simple but excellent photo. 10. like a piece of art!</td>', 'simple but excellent photo. 10. like a piece of art!', '2009-11-11 01:15:11.000000', NULL, 1),
(5722577, 831591, 56579, '<td valign="top">DNMC</td>', 'DNMC', '2009-11-11 01:34:44.000000', NULL, 1),
(5722581, 832897, 56579, '<td valign="top">Lacks focus, a subject like this really needs to be sharp.  Try using a smaller aperture</td>', 'Lacks focus, a subject like this really needs to be sharp.  Try using a smaller aperture', '2009-11-11 01:39:25.000000', NULL, 1),
(5722583, 832825, 56579, '<td valign="top">Lacks focus in the bright area in the center, the place where I would expect it most</td>', 'Lacks focus in the bright area in the center, the place where I would expect it most', '2009-11-11 01:40:00.000000', NULL, 1),
(5722632, 832827, 14867, '<td valign="top">Interesting and original work. Could be a real winner if the management of the (not symmetrical) reflexion was better (and actually, the subject itself isn''t perfectly centered).<br/>Already fascinating as is, with its threatening mood, and a nice graphical contrast against the saturated background.</td>', 'Interesting and original work. Could be a real winner if the management of the (not symmetrical) reflexion was better (and actually, the subject itself isn''t perfectly centered).Already fascinating as is, with its threatening mood, and a nice graphical contrast against the saturated background.', '2009-11-11 02:32:12.000000', NULL, 1),
(5722636, 832919, 14867, '<td valign="top">Nicely graphic, but not really symmetric....</td>', 'Nicely graphic, but not really symmetric....', '2009-11-11 02:33:01.000000', NULL, 1),
(5722644, 832073, 14867, '<td valign="top">Almost perfect, a bit more crop above was needed imho.</td>', 'Almost perfect, a bit more crop above was needed imho.', '2009-11-11 02:37:53.000000', NULL, 1),
(5722648, 832949, 14867, '<td valign="top">very clever (and beautiful) variation about the challenge''s theme.</td>', 'very clever (and beautiful) variation about the challenge''s theme.', '2009-11-11 02:40:52.000000', NULL, 1),
